import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        // Latest index of each vowel and of the latest non-vowel.
        long[] last = {-1, -1, -1, -1, -1};
        long bad = -1, answer = 0;
        String vowels = "aeiou";
        for (int i = 0; i < s.length(); i++) {
            int p = vowels.indexOf(s.charAt(i));
            if (p >= 0) last[p] = i;
            else bad = i;
            long lo = Math.min(Math.min(Math.min(last[0], last[1]), Math.min(last[2], last[3])), last[4]);
            answer += Math.max(0, lo - bad);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	var s string
	fmt.Fscan(bufio.NewReaderSize(os.Stdin, 1<<20), &s)
	// Latest index of each vowel and of the latest non-vowel.
	last := [5]int{-1, -1, -1, -1, -1}
	bad, answer := -1, 0
	for i := 0; i < len(s); i++ {
		if p := strings.IndexByte("aeiou", s[i]); p >= 0 {
			last[p] = i
		} else {
			bad = i
		}
		lo := last[0]
		for _, v := range last[1:] {
			lo = min(lo, v)
		}
		answer += max(0, lo-bad)
	}
	fmt.Println(answer)
}
